import{_ as e,o,c as a,a4 as s}from"./chunks/framework.bruR1JhL.js";const r="/tilepress/screenshots/watermark.webp",u=JSON.parse('{"title":"Edit, forms & OCR","description":"Change text and add objects to PDF pages, redact, make scans searchable, fill or design forms, and stamp watermarks.","frontmatter":{"title":"Edit, forms & OCR","description":"Change text and add objects to PDF pages, redact, make scans searchable, fill or design forms, and stamp watermarks."},"headers":[],"relativePath":"docs/edit.md","filePath":"docs/edit.md","lastUpdated":1795509372000}'),n={name:"docs/edit.md"};function i(d,t,l,h,g,c){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="edit-forms-ocr" tabindex="-1">Edit, forms &amp; OCR <a class="header-anchor" href="#edit-forms-ocr" aria-label="Permalink to &quot;Edit, forms &amp; OCR&quot;">​</a></h1><p>These tools change what is on a PDF&#39;s pages: retype text, add pictures and shapes, black out confidential text, add a searchable text layer to scans, fill in or create form fields, and stamp a watermark. In the app this category is the <strong>Edit &amp; Forms</strong> tab under <strong>Documents</strong>.</p><p>All four tools work on one open PDF, the same one the page tools use, so a file you opened in Split PDF or Rotate PDF is already open here. To open a PDF, drag it from the Explorer onto the tool, click <strong>Open PDF…</strong>, or click <strong>Use</strong> followed by the name of the PDF selected in the Explorer. Right-clicking a PDF in the Explorer and choosing <strong>Edit PDF</strong> opens it straight in Edit PDF. See <a href="/tilepress/docs/interface">The Tilepress window</a> for the Explorer and the other general controls.</p><p>Every tool saves a <strong>new</strong> file and leaves the original alone. When it&#39;s done, a <strong>Saved</strong> card lists the result with <strong>Open</strong>, <strong>Show in folder</strong> and <strong>Keep editing this file</strong>, which opens the result in the same tool for the next step. Each run is also listed in the <a href="/tilepress/docs/history">History</a>.</p><details class="details custom-block"><summary>How to type page ranges</summary><p>OCR PDF and Watermark PDF take a list of pages:</p><ul><li>Single pages and ranges, separated by commas or semicolons: <code>1-3, 5, 8-10</code>.</li><li>Open-ended ranges: <code>8-</code> means page 8 to the end, <code>-4</code> means pages 1 to 4.</li><li>The words <code>all</code>, <code>odd</code> and <code>even</code>.</li></ul><p>Leave the box empty to use every page.</p></details><h2 id="edit-pdf" tabindex="-1">Edit PDF <a class="header-anchor" href="#edit-pdf" aria-label="Permalink to &quot;Edit PDF&quot;">​</a></h2><p>Edit PDF lets you retype existing lines of text, add text, pictures, boxes, ellipses and highlights, cover things with white, and redact. Your changes are drawn into the pages when you save.</p><h3 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>Edit PDF</strong> and open a PDF.</li><li>Pick a tool in the toolbar above the page: <strong>Select</strong>, <strong>Edit text</strong>, <strong>Text</strong>, <strong>Image</strong>, <strong>Box</strong>, <strong>Ellipse</strong>, <strong>Highlight</strong>, <strong>White-out</strong> or <strong>Redact</strong>. A short hint for the chosen tool appears at the right of the toolbar.</li><li>Click or drag on the page: <ul><li><strong>Text</strong>: click to add a text box, or drag to give it a size. It starts with the word &quot;Text&quot;; type over it in the side panel.</li><li><strong>Box</strong>, <strong>Ellipse</strong>, <strong>Highlight</strong>, <strong>White-out</strong>, <strong>Redact</strong>: drag over the area. A plain click adds one at a standard size.</li><li><strong>Image</strong>: clicking the tool opens a file dialog. The picture is placed in the middle of the page.</li><li><strong>Edit text</strong>: every line of existing text gets a clickable area. Click a line to replace it (see <a href="#editing-existing-text">Editing existing text</a> below).</li></ul></li><li>After you add an object, the tool switches back to <strong>Select</strong>. Drag an object to move it, or drag its handles to resize it. Its settings appear in the side panel.</li><li>Use the page arrows or type a page number under the page to move between pages. You can change several pages before saving.</li><li>Click <strong>Save edited PDF…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><p>To remove an object, select it and press <kbd>Delete</kbd> (or <kbd>Backspace</kbd>), or click <strong>Delete (Del)</strong> in the side panel. <strong>Discard all</strong> removes every change you haven&#39;t saved. The <strong>Changes</strong> list shows how many objects you&#39;ve added on each page.</p><h3 id="editing-existing-text" tabindex="-1">Editing existing text <a class="header-anchor" href="#editing-existing-text" aria-label="Permalink to &quot;Editing existing text&quot;">​</a></h3><p>When you click a line with <strong>Edit text</strong>, Tilepress puts two objects on the page:</p><ul><li>a white-out box over the old line, set to also remove the old text from the file, and</li><li>a new text box with the same words, at the same size, in bold if the line was bold, and in the closest of the three fonts (Arial, Times New Roman or Courier New).</li></ul><p>The text field in the side panel gets the focus, so you can start typing. The whole line is replaced, not single words.</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><p>The side panel shows the settings of the selected object.</p><table tabindex="0"><thead><tr><th>Object</th><th>Settings</th><th>Defaults</th></tr></thead><tbody><tr><td>Text</td><td>The text itself (press <kbd>Enter</kbd> for a new line), <strong>Font</strong> (Arial, Times New Roman, Courier New), <strong>Size (pt)</strong> from 4 to 200, <strong>Colour</strong>, <strong>Bold</strong>, <strong>Italic</strong>, <strong>Opacity</strong></td><td>Arial, 14 pt, black, 100%</td></tr><tr><td>Image</td><td><strong>Opacity</strong></td><td>100%</td></tr><tr><td>Box, Ellipse</td><td><strong>Outline</strong> with its colour, <strong>Fill</strong> with its colour, <strong>Line width</strong> (0.5 to 20 pt), <strong>Opacity</strong></td><td>Red outline, no fill (light yellow when you tick <strong>Fill</strong>), 1.5 pt, 100%</td></tr><tr><td>Highlight</td><td><strong>Opacity</strong> (never more than 40%, so the text stays readable)</td><td>Yellow</td></tr><tr><td>White-out</td><td><strong>Also remove the text underneath</strong></td><td>Off</td></tr><tr><td>Redact</td><td>None. The text under the box is always deleted from the file.</td><td>Black</td></tr></tbody></table><p>Under the settings you see the object&#39;s position and size in points.</p><h3 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The file is suggested as <code>name_edited.pdf</code> next to the original. If that name is taken, it suggests <code>name_edited (2).pdf</code>.</li><li>Pictures can be JPG, PNG, GIF, BMP, TIFF or WebP. Transparent areas in PNGs stay transparent. Resizing a picture doesn&#39;t keep its proportions, so drag a corner carefully.</li><li>Text doesn&#39;t wrap inside its box. Start a new line with <kbd>Enter</kbd>.</li><li>Text is written with Arial, Times New Roman or Courier New taken from Windows and embedded in the PDF, so accented and non-Latin letters work. If a font file is missing, a standard PDF font is used instead, which only covers Latin letters.</li><li><strong>Edit text</strong> works on ordinary text PDFs. A scan has no text to find, so run <a href="#ocr-pdf">OCR PDF</a> on it first. The replacement text is always black at first; change <strong>Colour</strong> if the original was coloured.</li><li>Tilepress finds a &quot;line&quot; by grouping words at the same height. On a page with two columns, one line can run across both.</li><li>White-out only hides what is underneath unless you tick <strong>Also remove the text underneath</strong>. Hidden text can still be selected, copied and searched.</li></ul><div class="warning custom-block"><p class="custom-block-title">What Redact removes</p><p><strong>Redact</strong> draws a black box and deletes the text underneath, so it can&#39;t be copied or searched. A PDF stores text in pieces (a letter, a word or a whole line, depending on the program that made it). Tilepress deletes every piece that <strong>starts</strong> inside the box, so:</p><ul><li>make the box cover the start of everything you want gone, and</li><li>a piece that starts inside the box is deleted whole, even the part that sticks out.</li></ul><p>Pictures and drawings under the box are covered in black but stay in the file, and so does text inside embedded page objects (form XObjects). Check the saved file before you share it.</p></div><h2 id="ocr-pdf" tabindex="-1">OCR PDF <a class="header-anchor" href="#ocr-pdf" aria-label="Permalink to &quot;OCR PDF&quot;">​</a></h2><p>OCR PDF recognises the text in scanned pages and adds it as an invisible layer, so you can search the PDF and select and copy its text. The pages look exactly the same as before.</p><h3 id="how-to-use-it-1" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-1" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>OCR PDF</strong> and open a scanned PDF.</li><li>Check <strong>Engine</strong> and <strong>Document language</strong>. Tilepress picks them for you (see below).</li><li>If you only want some pages, type them in <strong>Pages</strong>.</li><li>Click <strong>Make searchable…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><p>A progress bar shows which page is being recognised. When it&#39;s done, a line under the options tells you how many pages were recognised, how many were skipped and how many words were found.</p><h3 id="options-1" tabindex="-1">Options <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Engine</strong></td><td><strong>Tesseract</strong> (only if it&#39;s installed) or <strong>Windows OCR (built in)</strong>.</td><td>Tesseract when it&#39;s installed, otherwise Windows OCR</td></tr><tr><td><strong>Document language</strong></td><td>The language of the text. The list shows the languages the chosen engine has.</td><td>English if Tesseract has it, otherwise the first one in the list</td></tr><tr><td><strong>Scan resolution</strong></td><td>How sharply each page is rendered before recognition: <strong>200 dpi (faster)</strong>, <strong>300 dpi (recommended)</strong> or <strong>400 dpi (small print)</strong>.</td><td>300 dpi</td></tr><tr><td><strong>Pages</strong></td><td>The pages to recognise. Empty means every page.</td><td>All pages</td></tr><tr><td><strong>Skip pages that already have text</strong></td><td>Leaves pages that already contain text (at least 20 characters) as they are.</td><td>On</td></tr></tbody></table><h3 id="good-to-know-1" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-1" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The file is suggested as <code>name_ocr.pdf</code> next to the original.</li><li>Tilepress needs one OCR engine: <ul><li><strong>Tesseract</strong>, if it&#39;s installed. Tilepress looks for <code>tesseract.exe</code> on the <code>PATH</code> and in a <code>Tesseract-OCR</code> folder under Program Files, Program Files (x86) or your local app data folder. It offers every language Tesseract has data for.</li><li><strong>Windows OCR</strong>, which comes with Windows 10 and 11. It offers the languages installed in <strong>Settings → Time &amp; language → Language</strong> that include &quot;Optical character recognition&quot;. These appear as language tags, such as <code>en-US</code>.</li></ul></li><li>If neither is available, the tool says so and the button stays greyed out.</li><li>Pick the language of the document. Recognising French text with English, for example, gives poor results.</li><li>Windows OCR can&#39;t read a page that is larger than 10,000 pixels on a side at the chosen resolution. Pick a lower resolution for very large pages.</li><li>Only the text layer is added: the page images aren&#39;t changed, compressed or straightened.</li><li>OCR runs on your computer. Nothing is uploaded.</li></ul><h2 id="pdf-forms" tabindex="-1">PDF Forms <a class="header-anchor" href="#pdf-forms" aria-label="Permalink to &quot;PDF Forms&quot;">​</a></h2><p>PDF Forms fills in the fields of an existing form, or adds new fields to any PDF so it becomes a form.</p><h3 id="how-to-use-it-2" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-2" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>PDF Forms</strong> and open a PDF.</li><li>Choose a mode at the top: <strong>Fill form</strong> (it shows how many fields the PDF has) or <strong>Design fields</strong>. A PDF with no fields opens in <strong>Design fields</strong>.</li></ol><h3 id="fill" tabindex="-1">Fill <a class="header-anchor" href="#fill" aria-label="Permalink to &quot;Fill&quot;">​</a></h3><ol><li>The side panel lists every field by name. A red <code>*</code> marks a required field.</li><li>Fill in the fields. Clicking a field on the page selects it in the list, and clicking a field in the list shows its page.</li><li>To make the answers a fixed part of the page, tick <strong>Flatten</strong>.</li><li>Click <strong>Save filled form…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><p>Text fields, multi-line fields, checkboxes, radio buttons, dropdowns and list boxes can be filled. Radio buttons, dropdowns and list boxes appear as a dropdown in the side panel. Signature fields and buttons aren&#39;t listed, and read-only fields are greyed out.</p><h3 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;Design&quot;">​</a></h3><ol><li>Pick a field type in the toolbar after <strong>Add:</strong>: <strong>Text box</strong>, <strong>Multi-line text</strong>, <strong>Checkbox</strong>, <strong>Dropdown</strong> or <strong>List box</strong>.</li><li>Click on the page to place a field at a standard size, or drag to size it.</li><li>Set its details in the side panel (see below).</li><li>To move or resize fields, click <strong>Select</strong> and drag them. Fields that were already in the PDF are shown in grey and can&#39;t be changed here.</li><li>Click <strong>Save form…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><h3 id="options-2" tabindex="-1">Options <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;Options&quot;">​</a></h3><p>Fill mode:</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Flatten</strong></td><td>Draws the answers into the page. The fields are removed, so the answers can no longer be changed.</td><td>Off</td></tr></tbody></table><p>Design mode, for the selected field:</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>The field&#39;s name. It must be unique in the PDF. Spaces become underscores.</td><td><code>field1</code>, <code>field2</code>…</td></tr><tr><td><strong>Options (one per line)</strong></td><td>The choices in a dropdown or list box.</td><td><code>Option 1</code> and <code>Option 2</code></td></tr><tr><td><strong>Default value</strong></td><td>The value the field starts with (not for checkboxes).</td><td>Empty (a dropdown starts on its first option)</td></tr><tr><td><strong>Required</strong></td><td>Marks the field as required.</td><td>Off</td></tr><tr><td><strong>Remove field</strong></td><td>Deletes the new field.</td><td></td></tr></tbody></table><h3 id="good-to-know-2" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-2" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Filled forms are suggested as <code>name_filled.pdf</code>, designed forms as <code>name_form.pdf</code>, next to the original.</li><li><strong>Save filled form…</strong> stays greyed out until you change a field. Only the fields you changed are written.</li><li><strong>Save form…</strong> stays greyed out while a new field has no name or a name that is already used.</li><li>New checkboxes start unticked. New fields use Helvetica, sized automatically to fit the box, with a grey border.</li><li>You can&#39;t create radio buttons or signature fields.</li><li>In the History, filling is listed as &quot;Fill PDF form&quot; and designing as &quot;Add PDF form fields&quot;.</li></ul><h2 id="watermark-pdf" tabindex="-1">Watermark PDF <a class="header-anchor" href="#watermark-pdf" aria-label="Permalink to &quot;Watermark PDF&quot;">​</a></h2><p>Watermark PDF stamps text or a picture on the pages, over or behind the content. In the app this tool is called <strong>Watermark</strong>. The preview shows the real result for the page you&#39;re looking at, made by the same code that saves the file.</p><p><img src="'+r+'" alt="Watermark PDF previewing a CONFIDENTIAL stamp on an invoice"></p><h3 id="how-to-use-it-3" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-3" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>Watermark</strong> and open a PDF.</li><li>Choose <strong>Text</strong> or <strong>Image</strong> at the top of the side panel. <ul><li>For text, type it in the box (it starts as <code>CONFIDENTIAL</code>) and pick the font, size and colour.</li><li>For an image, click <strong>Choose image…</strong> and set its size.</li></ul></li><li>Set the opacity, rotation and position. The preview updates as you go. Use the page arrows to check other pages.</li><li>Click <strong>Add watermark and save…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><h3 id="options-3" tabindex="-1">Options <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Text</strong> / <strong>Image</strong></td><td>What to stamp.</td><td>Text</td></tr><tr><td>Text box</td><td>The watermark text.</td><td><code>CONFIDENTIAL</code></td></tr><tr><td><strong>Font</strong></td><td>Arial, Times New Roman or Courier New.</td><td>Arial</td></tr><tr><td><strong>Size (pt)</strong></td><td>Text size, 6 to 300 points.</td><td>60</td></tr><tr><td><strong>Colour</strong></td><td>Text colour.</td><td>Red</td></tr><tr><td><strong>Bold</strong></td><td>Bold text.</td><td>On</td></tr><tr><td><strong>Choose image…</strong></td><td>The picture: JPG, PNG, GIF, BMP, TIFF or WebP.</td><td></td></tr><tr><td><strong>Size (% of page width)</strong></td><td>Width of the picture as a share of the page width, 5 to 100%.</td><td>40%</td></tr><tr><td><strong>Opacity</strong></td><td>How solid the watermark is, 5 to 100%.</td><td>25%</td></tr><tr><td><strong>Rotation</strong></td><td>From -90° to 90°, in steps of 5°. Positive values turn it anticlockwise.</td><td>45°</td></tr><tr><td><strong>Position</strong></td><td>One of nine spots in a 3 × 3 grid: corners, edges or centre.</td><td>Centre</td></tr><tr><td><strong>Repeat across the page (tile)</strong></td><td>Repeats the watermark in staggered rows over the whole page instead. Untick it to go back to the centre.</td><td>Off</td></tr><tr><td><strong>Layer</strong></td><td><strong>Over the content</strong> or <strong>Behind the content</strong>.</td><td>Over the content</td></tr><tr><td><strong>Pages</strong></td><td>The pages to stamp. Empty (shown as &quot;All&quot;) stamps every page.</td><td>All pages</td></tr></tbody></table><h3 id="good-to-know-3" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-3" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The file is suggested as <code>name_watermarked.pdf</code> next to the original.</li><li>Positions at the edges and corners keep a margin of half an inch (about 13 mm) from the page edge.</li><li>Tiles are spaced so they don&#39;t overlap, whatever the rotation.</li><li><strong>Behind the content</strong> puts the watermark under everything on the page. On a scanned page, the scan is one big picture that hides it. The preview shows you whether it can be seen.</li><li>Text uses Arial, Times New Roman or Courier New from Windows, embedded in the PDF, so accented and non-Latin letters work.</li><li>Transparent areas of a PNG stay transparent.</li><li>To watermark images rather than PDFs, use <a href="/tilepress/docs/img-edit">Watermark Image</a>.</li></ul>',55)])])}const f=e(n,[["render",i]]);export{u as __pageData,f as default};
